-- Отели (сейчас Турция: Анталья, Кемер, Белек, Аланья, Сиде), данные Google Travel, цены на 28-29.10.2026.
-- Источник: dataset/hotels_turkey.csv
--
-- Сырые тексты Google (удобства и расположение) загружаются во временную таблицу raw_hotels,
-- а в hotels попадают только признаки, по которым можно фильтровать через SQL.
-- Миграцию можно запускать повторно.

CREATE TABLE IF NOT EXISTS hotels (
    id                  SERIAL PRIMARY KEY,
    country             VARCHAR(50)   NOT NULL,
    city                VARCHAR(50)   NOT NULL,   -- Анталья, Кемер, Белек, Аланья, Сиде
    name                VARCHAR(200)  NOT NULL,
    rating              NUMERIC(2, 1),            -- оценка отеля (0-5)
    stars               SMALLINT CHECK (stars BETWEEN 1 AND 5), -- NULL, если категория не указана
    price_per_night_rub INT           NOT NULL,   -- стоимость за ночь в рублях
    google_url          TEXT,                     -- страница отеля в Google Travel
    official_site       TEXT,                     -- NULL, если не найден

    free_breakfast      BOOLEAN NOT NULL DEFAULT FALSE, -- «Бесплатный завтрак»
    all_inclusive       BOOLEAN NOT NULL DEFAULT FALSE, -- есть тариф «Все включено»
    pool                BOOLEAN NOT NULL DEFAULT FALSE, -- любой бассейн (открытый, крытый, несколько)
    kids_friendly       BOOLEAN NOT NULL DEFAULT FALSE, -- только явная отметка «Подходит для детей» (в данных редкая)
    pets_allowed        BOOLEAN NOT NULL DEFAULT FALSE, -- «Можно с домашними животными»
    airport_transfer    BOOLEAN NOT NULL DEFAULT FALSE, -- трансфер между аэропортом и отелем
    spa                 BOOLEAN NOT NULL DEFAULT FALSE,
    fitness             BOOLEAN NOT NULL DEFAULT FALSE,
    free_parking        BOOLEAN NOT NULL DEFAULT FALSE,
    free_wifi           BOOLEAN NOT NULL DEFAULT FALSE,
    kitchen             BOOLEAN NOT NULL DEFAULT FALSE, -- кухня или мини-кухня в номере
    restaurant          BOOLEAN NOT NULL DEFAULT FALSE,
    beachfront          BOOLEAN NOT NULL DEFAULT FALSE, -- «первая линия»: выход к пляжу / свой пляж / отель прямо на берегу
    beach_minutes       SMALLINT,                       -- минуты до ближайшего пляжа (NULL, если указаны только километры)
    beach_on_foot       BOOLEAN,                        -- TRUE пешком, FALSE на транспорте, NULL способ не указан

    UNIQUE (city, name)
);

DROP TABLE IF EXISTS pg_temp.raw_hotels;
CREATE TEMP TABLE raw_hotels (
    country             VARCHAR(50),
    city                VARCHAR(50),
    name                VARCHAR(200),
    rating              NUMERIC(2, 1),
    stars               SMALLINT,
    price_per_night_rub INT,
    google_url          TEXT,
    official_site       TEXT,
    distance_to_sea     TEXT,
    features            TEXT
);

;

-- Расстояние до пляжа (beach_minutes) из distance_to_sea. Форматы в данных:
--    «Ближайший пляж по Google: Lara Beach 10 мин на такси | пешком | на автобусе»
--    «ближайший пляж Konyaaltı ~11 мин (Google, способ не указан)»
--    «5 минут пешком до пляжа Мермерли»
--    «7 мин езды до Lara Beach» (когда в описании только километры)
-- beachfront: фразы в описании расположения либо отметка «Выход к пляжу».
--    Одной отметке не верим, если до пляжа больше 10 минут: Google ставит её и отелям,
--    у которых пляж далеко (Qinn Hotels: 21 мин на такси, Адонис: ~10 км).
     free_breakfast, all_inclusive, pool, kids_friendly, pets_allowed, airport_transfer,
     spa, fitness, free_parking, free_wifi, kitchen, restaurant,
     beachfront, beach_minutes, beach_on_foot)
SELECT
    r.country, r.city, r.name, r.rating, r.stars, r.price_per_night_rub, r.google_url, r.official_site,
    COALESCE(r.features, '') ILIKE '%Бесплатный завтрак%',
    COALESCE(r.features, '') ILIKE '%Все включено%',
    COALESCE(r.features, '') ILIKE '%бассейн%',
    COALESCE(r.features, '') ILIKE '%Подходит для детей%',
    COALESCE(r.features, '') ILIKE '%домашними животными%',
    COALESCE(r.features, '') ILIKE '%Трансфер между аэропортом%',
    COALESCE(r.features, '') ILIKE '%Спа-салон%',
    COALESCE(r.features, '') ILIKE '%Фитнес-центр%',
    COALESCE(r.features, '') ILIKE '%Бесплатная парковка%',
    COALESCE(r.features, '') ILIKE '%Бесплатный Wi-Fi%',
    COALESCE(r.features, '') ILIKE '%Кухня%' OR COALESCE(r.features, '') ILIKE '%мини-кух%',
    COALESCE(r.features, '') ILIKE '%Ресторан%',
    (COALESCE(r.features, '') ILIKE '%Выход к пляжу%' AND COALESCE(bm.minutes, 0) <= 10)
        OR COALESCE(r.distance_to_sea, '') ~* (
            'собственн\w+ пляж|расположен на пляже|на пляже (Белека|у залива)|расположен у пляжа'
            || '|напротив пляжа|через дорогу от пляжа|рядом с пляжем|расположен на берегу'
            || '|расположен возле\s+средиземноморского пляжа|пляжный (отель|курорт)'
            || '|до моря 2 минуты|две минуты (пешком|ходьбы)'
        ),
    bm.minutes,
    CASE
        WHEN bm.minutes IS NULL THEN NULL
        WHEN r.distance_to_sea ~ 'Google:[^|]*(на такси|на автобусе)' THEN FALSE
        WHEN r.distance_to_sea ~ 'Google:[^|]*пешком'                 THEN TRUE
        WHEN r.distance_to_sea ~ '(пешком|дойти пешком) до пляжа'     THEN TRUE
        WHEN r.distance_to_sea ~ '\d+ мин\w* езды до [^;|]*Beach'    THEN FALSE
        ELSE NULL
    END
FROM raw_hotels r
CROSS JOIN LATERAL (
    SELECT COALESCE(
        substring(r.distance_to_sea from 'Google:[^0-9|]*(\d+) мин')::SMALLINT,
        substring(r.distance_to_sea from 'пляж[^~;|]*~(\d+) мин')::SMALLINT,
        substring(r.distance_to_sea from '(\d+) мин\w* (?:пешком|ходьбы) до пляжа')::SMALLINT,
        substring(r.distance_to_sea from '(\d+) мин\w* езды до [^;|]*Beach')::SMALLINT
    ) AS minutes
) bm
ON CONFLICT (city, name) DO NOTHING;

DROP TABLE raw_hotels;
